CREATE FUNCTION public.interpretation_annotation_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.measured_value IS NOT NULL AND (NEW.unit IS NULL OR position(NEW.unit in NEW.source_quote)=0 OR position(NEW.measured_value::text in NEW.source_quote)=0) THEN RAISE EXCEPTION 'Measured values require the literal value and raw unit in source evidence';END IF; RETURN NEW;END $$;
CREATE TRIGGER interpretation_annotation_guard BEFORE INSERT OR UPDATE ON public.design_interpretations FOR EACH ROW EXECUTE FUNCTION public.interpretation_annotation_guard();
CREATE FUNCTION public.interpretation_review_immutable() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_OP='UPDATE' THEN RAISE EXCEPTION 'Interpretation review history is immutable';END IF;RETURN OLD;END $$;
CREATE TRIGGER interpretation_review_immutable BEFORE UPDATE ON public.design_interpretation_reviews FOR EACH ROW EXECUTE FUNCTION public.interpretation_review_immutable();
CREATE FUNCTION public.interpretation_archive_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.deleted_at IS NOT NULL AND OLD.deleted_at IS NULL AND EXISTS(SELECT 1 FROM public.design_interpretation_runs WHERE document_id=NEW.id AND status='running') THEN RAISE EXCEPTION 'Wait for drawing interpretation before deletion';END IF;RETURN NEW;END $$;
CREATE TRIGGER interpretation_archive_guard BEFORE UPDATE ON public.design_documents FOR EACH ROW EXECUTE FUNCTION public.interpretation_archive_guard();